insert into public.settings (store_id, data) select (select id from public.stores where slug = $j$loja$j$), $j${"store_name":"Nome da Loja","logo_url":"images/logo.png","announcement":"Padaria, confeitaria e café · encomende pelo site","hours_short":"Seg–Sex 8h–19h · Sáb 8h–14h","hero_eyebrow":"padaria e confeitaria artesanal","hero_title":"Feito hoje cedo, para a sua mesa.","hero_text":"Pães, bolos, croissants e doces feitos todos os dias, com ingredientes de verdade. Encomende pelo site e retire na hora marcada.","hero_image":"images/cafe-hero.jpg","poster_image":"images/cafe-poster-wide.jpg","hero_bg_image":"images/cafe-fundo.jpg","cafe_bg_image":"images/cafe-rodape.jpg","hero_stats":[{"value":"Desde 2010","label":"Na cidade"},{"value":"+40","label":"Receitas"},{"value":"10 mil","label":"No Instagram"}],"cafe_eyebrow":"Nosso café","cafe_title":"Um café à altura dos nossos doces.","cafe_text":"Espresso tirado na hora, bebidas geladas e a vitrine da confeitaria no balcão. Sente, peça a fatia do dia e fique à vontade.","cafe_items":[{"title":"Vinte jeitos de café","text":"Espresso, coado, com leite ou gelado. O cardápio inteiro está logo aqui embaixo.","image":"images/cafe-graos.jpg"},{"title":"Bebidas da casa","text":"Caramelo, chantilly, canela e chocolate. Pergunte qual é a da estação.","image":"images/cafe-caramelo.jpg"},{"title":"Espresso na hora","text":"Tirado na máquina quando você pede e servido na porcelana.","image":"images/cafe-espresso.jpg"}],"features_eyebrow":"por que escolher a gente","features_title":"O cuidado que você sente na primeira mordida","videos_eyebrow":"na nossa cozinha","videos_title":"Veja de onde sai o seu bolo.","news_eyebrow":"os mais pedidos","news_title":"Bolos que viram o assunto da festa","news_text":"Escolha o bolo e a gente confirma tamanho, sabor e valor no WhatsApp.","bake_eyebrow":"saindo do forno","bake_title":"Folhados e croissants fresquinhos todos os dias.","menu_eyebrow":"escolha o seu","cafe_menu_eyebrow":"Cafeteria","cafe_menu_title":"Escolha o café. A fatia a gente escolhe junto.","cafe_menu_text":"Quentes, com leite ou gelados, para tomar no balcão com a fatia do dia.","menu_title":"Nosso cardápio","highlight_title":"Encomendar leva 2 minutos","highlight_items":[{"label":"1. Escolha","value":"Adicione os produtos"},{"label":"2. Envie","value":"Dia, horário e WhatsApp"},{"label":"3. Confirmamos","value":"Valor e pagamento no chat"},{"label":"Bolos de festa","value":"48h de antecedência"}],"visit_eyebrow":"venha nos visitar","visit_title":"Duas portas, o mesmo carinho.","visit_text":"Na padaria você retira a encomenda e leva o pão da semana. No café você senta, pede uma bebida e escolhe a fatia do dia.","address":"Rua Exemplo, 123 · Centro","city":"Sua Cidade, UF","phone":"(00) 00000-0000","whatsapp":"","instagram":"https://instagram.com/","maps_url":"https://www.google.com/maps","hours":[{"label":"Segunda a sexta","value":"8h – 19h"},{"label":"Sábado","value":"8h – 14h"},{"label":"Domingo","value":"Fechado"}],"locations":[{"name":"Nome da Loja","kind":"Padaria e Confeitaria","image":"images/banco-bolo-de-morango-com-chantilly.jpg","address":"Rua Exemplo, 123 · Centro","city":"Sua Cidade, UF","maps_url":"https://www.google.com/maps","instagram":"https://instagram.com/","week":["","08:00-19:00","08:00-19:00","08:00-19:00","08:00-19:00","08:00-19:00","08:00-14:00"]},{"name":"Nome do Café","kind":"Cafeteria","image":"images/cafe-hero.jpg","address":"Avenida Exemplo, 456 · Bairro","city":"Sua Cidade, UF","maps_url":"https://www.google.com/maps","instagram":"https://instagram.com/","week":["","09:00-20:00","09:00-20:00","09:00-20:00","09:00-20:00","09:00-20:00","09:00-16:00"]}],"newsletter_title":"Receba as novidades da semana","newsletter_text":"Um e-mail por mês com lançamentos e datas especiais.","footer_about":"Padaria, confeitaria e café. Tudo feito na nossa cozinha, todos os dias.","wa_message":"Olá! Vim pelo site e quero fazer uma encomenda.","footer_text":"© 2026 Nome da Loja · Padaria e Café","offer_on":false,"offer_eyebrow":"para a sua primeira encomenda","offer_title":"10% de desconto e a garantia de que vai sair do jeito que você pediu.","offer_text":"Use o cupom na primeira encomenda pelo site. Se o pedido não sair como combinado, a gente refaz sem custo. Simples assim.","offer_code":"PRIMEIRA10","offer_percent":10,"offer_note":"Vale uma vez por cliente, para produtos com preço no site. Não acumula com outras promoções.","verse_text":"Provai e vede que o Senhor é bom.","verse_ref":"Salmos 34:8","facebook":"https://www.facebook.com/","email":"contato@minhaloja.com.br","accept_orders":true,"min_notice_hours":0,"delivery_fee":0,"payment_methods":["pix","dinheiro","cartao"],"timezone":"America/Sao_Paulo"}$j$::jsonb on conflict (store_id) do nothing;
